fn solve(input: Vec<char>) -> Vec<char> {
    // Convert Vec<char> to String for easier manipulation
    let input_str: String = input.iter().collect();
    
    // Check the prefix and suffix
    if !input_str.starts_with("AtCoder ") || !input_str.ends_with(" Contest\n") {
        return vec![]; // Return empty if the format is incorrect
    }
    
    // Find the start of the name
    let name_start = "AtCoder ".len();
    let name_end = input_str.len() - " Contest\n".len();
    
    // Extract the name
    let name = &input_str[name_start..name_end];
    
    // Check if the name is valid
    if name.is_empty() || !name.chars().next().unwrap().is_uppercase() {
        return vec![]; // Return empty if the name is invalid
    }
    
    // Build the result using the first character of the name
    let initial = name.chars().next().unwrap();
    build_result(initial)
}

fn build_result(ch: char) -> Vec<char> {
    let mut result = Vec::new();
    result.push('A');
    result.push(ch);
    result.push('C');
    result.push('\n');
    result
}